"""Construit Article_resserre.docx et Supplementary_Data_resserre.docx à partir des versions de référence
(Article.docx md5 68caaeb7…, Supplementary_Data.docx md5 3b6f95e4…). Les passages retirés du texte principal
sont déplacés VERBATIM dans une nouvelle Note S2 du supplément ; l'ancienne Note S2 devient Note S3."""
import docx, re, copy, hashlib, json
M = 'docs/manuscrit/'  # lancer depuis la racine du dépôt (python3 avec python-docx)
from docx.shared import RGBColor, Pt
from docx.oxml.ns import qn

assert hashlib.md5(open(M + 'Article.docx', 'rb').read()).hexdigest() == '68caaeb7c55ec2716a7fa36010d898dd'
assert hashlib.md5(open(M + 'Supplementary_Data.docx', 'rb').read()).hexdigest() == '3b6f95e4f6ac72b5dc773f53c061d483'
A = docx.Document(M + 'Article.docx'); S = docx.Document(M + 'Supplementary_Data.docx')
P = list(A.paragraphs); SP = list(S.paragraphs)
ORIG = {i: p.text for i, p in enumerate(P)}
BLUE = RGBColor(0x1F, 0x4E, 0x79); GREY = RGBColor(0x88, 0x88, 0x88)
ITAL = ['Chondrostoma nasus', 'Parachondrostoma toxostoma', 'C. nasus', 'P. toxostoma', 'Neotoma', 'Takifugu',
        'Aspidoscelis', 'Kikihia', 'Escherichia coli', 'Salmonella enterica', 'Enterococcus faecalis',
        'Staphylococcus aureus']
IT_RE = re.compile('(' + '|'.join(re.escape(t) for t in ITAL) + ')')

def isgrey(r): return r.font.color is not None and r.font.color.type is not None and str(r.font.color.rgb) == '888888'
def nongrey(p): return ''.join(r.text for r in p.runs if not isgrey(r))

def add_runs(p, text, color=BLUE, before=None, bold_lead=None):
    pieces = []
    if bold_lead: pieces.append((bold_lead + ' ', False, True))
    for k, seg in enumerate(IT_RE.split(text)):
        if seg: pieces.append((seg, k % 2 == 1, False))
    for seg, it, bd in pieces:
        r = p.add_run(seg); r.italic = it or None; r.bold = bd or None
        if color is not None: r.font.color.rgb = color
        if before is not None: before.addprevious(r._r)

def set_text(p, text):
    """Remplace le texte non gris ; conserve les notes grises (placées après le nouveau texte)."""
    grey = [r for r in p.runs if isgrey(r)]
    for r in list(p.runs):
        if not isgrey(r): r._r.getparent().remove(r._r)
    add_runs(p, text, before=grey[0]._r if grey else None)

def set_grey(p, text):
    for r in list(p.runs):
        if isgrey(r): r._r.getparent().remove(r._r)
    r = p.add_run(text); r.italic = True; r.font.size = Pt(9); r.font.color.rgb = GREY

def delete(p): p._element.getparent().remove(p._element)

NEW = {}   # index -> nouveau texte (non gris)
DEL = []   # index supprimés du texte principal
MOVED = {} # index -> destination

# ----------------------------------------------------------------------------- Background
NEW[7] = ("Animals and their microbial communities form composite biological units in which microbial composition contributes to host performance and to tolerance of environmental constraints [1]. These associations are established largely by the sorting of environmental microbial pools according to host ecology and physiology — feeding behaviour and the immune pathways underlying tolerance of or resistance to microbes [2–4]. Environmental acquisition is particularly important in fish, which live in a medium favourable to bacterial growth, are continuously exposed to microbes at their epithelial barriers and are mostly oviparous, with limited maternal effects compared with mammals [5]; surveys of wild populations accordingly report a predominant environmental component of variation in bacterial composition [6–8]. Host genotype is nonetheless not without effect. In wild baboons followed over fourteen years, microbiome phenotypes were almost universally heritable, but with a typically low, context-dependent heritability that only large samples can quantify [9]; in stickleback, a host genetic influence on the gut microbiome became measurable once biological and technical components of variance had been decomposed [10]. Any effect of host ancestry on the fish microbiota is therefore expected to be small relative to the environmental one, and detecting it requires large samples and explicit control of the spatial and technical axes along which it could be mimicked.")
NEW[8] = ("Secondary contact zones make host ancestry a naturally occurring and naturally replicated variable. Introgressive hybridisation may disrupt co-adapted gene complexes and thereby alter close host–microbe interactions [11]; conversely, hybridisation is a source of genomic diversity and adaptive novelty [12, 13], which may extend to the microbiota through the acquisition of new microbial taxa. Three outcomes are usually contrasted: an intermediate microbiota, varying monotonically with ancestry; dominance, in which hybrids resemble one parental species; and a transgressive microbiota, lying outside the range of both parents. Camper et al. [14] formalised this comparison for host-associated microbiomes with four idealised models of taxon membership — Union, Intersection, Gain and Loss — whose relative weights sum to one; the Gain–Loss axis gives an operational definition of a transgressive microbiota that does not presuppose a cost to the host. The distinction matters: on an ecologically successful hybrid lizard, widespread transgressive segregation was correlated with a restructuring of niche, and the authors argue that the equation of transgression with dysbiosis rests disproportionately on hybrids of low adaptive value [15]. Following the framework's own statement of scope, we read the index as describing a pattern and not a process.")
NEW[9] = ("What is known of hybrid microbiota in fish comes almost entirely from controlled crosses: genotype corresponds closely to intestinal characteristics in reciprocal hybrids of bream and culter, whose parents have contrasting feeding habits [16]; host hybridisation outweighs cohabitation in intrageneric Takifugu hybrids [17]; reciprocal hybrids of koi and goldfish resemble one parent rather than the midpoint of the two [18]; and whitefish species pairs and their hybrids have been compared in natural and controlled environments [19] (reviewed in [20]). Studies of natural hybrid zones in other vertebrates do not converge. Host ancestry predominates in Neotoma woodrats, where habitat determines diet but genotype determines the gut microbiota [21], and in hybridising brown lemurs [22]; site soil properties rather than genetic ancestry explain the gut microbiota of baboons spanning a hybrid zone [23], and an apparent effect of admixture in wild house mice becomes weak once spatial autocorrelation is taken into account [24]. In hybridising chickadees moved to a common environment, the change of environment affected richness but not composition, while an effect of ancestry on composition was not supported [25] — an argument for reporting alpha and beta diversity separately. No study yet combines a natural hybrid zone in fish, host ancestry quantified by genotyping rather than assigned by cross class, and several tissue compartments characterised in the same individual.")
NEW[10] = ("The nase Chondrostoma nasus and the South-west European nase, or toxostome, Parachondrostoma toxostoma offer that combination. The toxostome is endemic to southern France, where it is declining and is a species of conservation concern; the nase, native to central Europe, entered the Rhône basin through navigable connections built across Europe during the last century [26], so that the two distributions have partially overlapped for about a hundred years. Hybridisation occurs in the patchily distributed sympatric areas of the basin, with an incidence unrelated to habitat characteristics [27–29] — the configuration of a mosaic hybrid zone [30]. Guivier et al. [31] characterised four tissue compartments of the two species in strict parapatry on a single river: the tissue compartment was the first factor of variation, externally and internally exposed tissues contrasted markedly, and species-specific taxa were asymmetric between compartments, numerous on the external tissues of the nase and in the intestine of the toxostome. They proposed that introgressive hybridisation might affect the microbiota differently depending on the tissue, a question their sixteen fish at two stations could not address. The present study addresses it on 180 fish sampled at nine stations over six watercourses of the Rhône drainage in two years, with host ancestry resolved by genotyping across 25 chromosomes and the same four compartments — caudal fin, gill, midgut and hindgut — characterised in each individual.")
NEW[11] = ("We ask whether the microbiota of individuals of mixed ancestry is intermediate between the two parental species, dominated by one of them or displaced outside their range, and whether the answer is the same in all four compartments. Three features of the design shape how the answer is reported. First, genotyping separates intermediate genomes from near-parental genomes introgressed on one or a few chromosomes, so that what counts as a hybrid is a decision: every contrast is run on intermediate hybrids alone and on all hybrids, both passes being declared in advance. Second, the comparison is reported both as a category contrast across stations and as the four-dimensional (4H) index of Camper et al. [14], whose settings are fixed a priori and whose sensitivity is reported. Third, genotypic category is entangled with station, the strongest correlate of composition, and with plate position, which followed field processing order; category effects are therefore bracketed between the two sequential orderings, with plate position as a covariate in a sensitivity analysis, and read as patterns co-varying with station and category rather than as effects of ancestry alone. Following Guivier et al. [31], we expect any hybrid signal to be most pronounced in the digestive compartments, where the two parental species diverge most.")

# ----------------------------------------------------------------------------- Methods
NEW[16] = ("We studied the host-associated bacterial microbiota of two interbreeding cyprinid fishes, the nase Chondrostoma nasus (code Cn) and the toxostome Parachondrostoma toxostoma (code Pt), and of their hybrids (code Hy), in their contact zone. Fish were sampled at nine stations of the Rhône drainage (rivers Durance, Suran, Buech, Beaume and Ardèche, and one canal fed by the Largue; south-eastern France) in 2014 and 2015, spanning a gradient of hybrid-zone context (allopatry, sympatry with hybridisation, asymmetric introgression). Two stations lie on the Suran, 25.4 km apart and separated by a barrier passable only downstream; they are treated as distinct because they carry different taxa.")
NEW[19] = ("Stations, coordinates, collection dates, genotypic composition and the numbers of individuals and libraries per station are given in Supplementary Table S1; coordinates and dates are field records supplied by the collecting team (see the note to Table S1). Individuals are counted per site code and year of sampling, which gives 180 individuals (156 if years are collapsed, because individual numbering restarts each year).")
DEL += [20]
NEW[21] = ("Species identity was resolved by genotyping rather than by morphology. Each individual was assigned, from a chromosome-level assignment across 25 chromosomes, to one of three categories — Cn (59 individuals), Hy (42) and Pt (79) — and not by thresholding a median hybrid index, because a substantial minority of hybrids carry an extreme median index and are identified by their inter-chromosome discordance. Genotypes were obtained from Q-scores on liver tissue for 175 individuals; of the remaining five, all parental, three were resolved from Q-score fits on midgut and caudal fin and two by an earlier, closely related method that left no Q-score record (Supplementary Table S2). Nine of the 49 individuals previously identified on morphology were reclassified. The Hy category comprises 20 intermediate genomes and 22 near-parental genomes, introgressed on a single chromosome in 17 cases, on two in four and on six in one. Every analysis of category is therefore run twice, both passes being declared in advance: pass 1 retains the 20 intermediate hybrids and excludes the 22 near-parental individuals, which are not reassigned to a parental category (158 individuals); pass 2 retains all 42 (180 individuals). Three stations carry all three categories — 74 individuals in pass 2 and 65 in pass 1, where Saint-Just-d'Ardèche retains a single hybrid — the subset in which the hybrid contrast can be tested within a station.")
NEW[26] = ("Bacterial DNA was extracted from each tissue with the Qiagen Food Mericon kit (Qiagen, Venlo, Netherlands), following a slightly modified protocol detailed in Guivier et al. [31]. A 251 bp fragment of the V4 region of the bacterial 16S rRNA gene was amplified with the dual-index method of Kozich et al. [32], with primers 515F GTGCCAGCMGCCGCGGTAA and 806R GGACTACHVGGGTWTCTAAT carrying an 8 bp index and Illumina adapters; amplification, purification and pooling followed Galan et al. [33]. Libraries were quantified with the Kapa quantification kit (Kapa Biosystems) and sequenced on an Illumina MiSeq with reagent kit v3 (2 × 251 bp paired-end reads, two 8 bp index reads) and a 10 % PhiX spike-in, on 10 July (durance1), 5 October (durance2) and 3 November 2017 (durance3).")
NEW[27] = ("The 768 samples were processed through two independent library preparations, each by the one-step dual-index PCR of Kozich et al. [32]. The first library was sequenced once (run durance1); the second, prepared from an independent PCR of the same samples, was sequenced twice on separate flow cells (durance2 and durance3). Because indices are incorporated during amplification, the two preparations carry different index assignments on the same plate layout (Supplementary Table S3). Each biological sample is thus represented three times in a nested structure — two library preparations, and two sequencing runs within the second — which separates the variability contributed by library preparation from that contributed by sequencing alone, neither being confounded with any biological factor; the structure was verified on the deposited data (Supplementary Note S1).")
DEL += [28]
NEW[30] = ("Negative controls comprised four extraction blanks, one per tissue, and eight no-template PCR controls, each sequenced in all three runs (36 negative-control samples). Two aliquots of the ZymoBIOMICS Microbial Community Standard (Zymo Research, cat. D6300), a defined mixture of eight bacterial taxa, served as positive controls (six mock samples across runs), and 25 empty wells that received no library were sequenced in all three runs (75 samples) to monitor index hopping. The biological samples, controls and empty wells deposited are listed in Supplementary Table S4.")
DEL += [31]; MOVED[30] = 'Note S2 (Controls)'
NEW[33] = ("Reads were processed with a version-controlled pipeline (cutadapt 5.0 [34]; R 4.5.3 with DADA2 1.38.0 [35]; SILVA v138.2 [36]; BLAST+ 2.13.0; FastQC and MultiQC), each run being processed separately through denoising. The 16S V4 primers co-amplify the host mitochondrial 12S rRNA gene (15–67% of reads per sample); because the host amplicon (~190 bp) is shorter than the bacterial one (~253 bp), host reads were removed by length with cutadapt. Amplicon sequence variants (ASVs) were inferred per run with DADA2 after quality filtering and truncation, with error models learned per run; the three sequence tables were merged keeping runs distinct, chimeras were removed (consensus method) and taxonomy was assigned against SILVA with the naïve Bayesian classifier and exact species matching. ASVs assigned to Eukaryota, Chloroplast or Mitochondria, or unassigned at the domain level, were removed. Parameters and their justification are given in Supplementary Note S2.")
